const item = $input.first().json;
const body = item.body || item;
const text = String((body.content || '') + ' ' + (body.text || '') + ' ' + (body.subject || '') + ' ' + (body.clean_body || ''));

// Phone extraction
const phoneMatch = text.match(/(?:\+84|0)[1-9]\d{8,9}/);
const extracted_phone = phoneMatch ? phoneMatch[0] : (body.phone || '0905123456');

// Budget extraction
let extracted_budget = 0;
if (text.match(/(\d+)\s*(?:tỷ|ty)/i)) {
  extracted_budget = parseInt(text.match(/(\d+)\s*(?:tỷ|ty)/i)[1], 10) * 1000000000;
} else if (text.match(/(\d+)\s*(?:triệu|trieu|tr|million)/i)) {
  extracted_budget = parseInt(text.match(/(\d+)\s*(?:triệu|trieu|tr|million)/i)[1], 10) * 1000000;
} else if (text.match(/(\d+)\s*(?:k|nghìn|nghin)/i)) {
  extracted_budget = parseInt(text.match(/(\d+)\s*(?:k|nghìn|nghin)/i)[1], 10) * 1000;
} else if (body.budget) {
  extracted_budget = Number(body.budget);
} else {
  extracted_budget = 30000000;
}

// Company extraction
let extracted_company = body.company || body.company_name || '';
if (!extracted_company) {
  const compMatch = text.match(/(?:Tập đoàn|Công ty(?:\s+TNHH|\s+Cổ phần)?|Doanh nghiệp)\s+[^\n,.-]+/i);
  extracted_company = compMatch ? compMatch[0].trim() : 'Doanh nghiệp đối tác';
}

// Name extraction
let extracted_name = body.sender_name || body.name || '';
if (!extracted_name && body.sender_email) {
  extracted_name = body.sender_email.split('@')[0];
}
if (!extracted_name) extracted_name = 'Khách hàng tiềm năng';

return [{
  json: {
    ...body,
    sender_email: (body.sender_email || body.email || 'lead@enterprise.vn').trim(),
    extracted_name,
    extracted_phone,
    extracted_company,
    extracted_budget,
    extracted_requirement: body.content || body.subject || 'Tư vấn giải pháp tự động hóa email'
  }
}];

const item = $input.first().json;
const budget = Number(item.extracted_budget || 0);

let campaign_segment = 'SME_RETAIL';
let campaign_tag = 'CAMPAIGN_GROWTH_SME';

if (budget >= 70000000) {
  campaign_segment = 'ENTERPRISE_HIGH_VALUE';
  campaign_tag = 'CAMPAIGN_ENTERPRISE_2026';
} else if (budget >= 30000000) {
  campaign_segment = 'MID_MARKET';
  campaign_tag = 'CAMPAIGN_MID_2026';
}

return [{
  json: {
    ...item,
    campaign_segment,
    campaign_tag
  }
}];

const item = $input.first().json;
let phone = String(item.extracted_phone || '').trim();
if (phone.startsWith('0')) {
  phone = '+84' + phone.substring(1);
}

const cleanCompany = String(item.extracted_company || 'Doanh nghiệp đối tác')
  .replace(/^=+/, '').trim();
const cleanName = String(item.extracted_name || 'Khách hàng')
  .replace(/^=+/, '').trim();

return [{
  json: {
    ...item,
    clean_phone: phone,
    clean_company: cleanCompany,
    clean_name: cleanName
  }
}];

const raw = $('4. Sanitize Extracted Entities Code').first().json;
const dbCheck = $input.first().json;
const budget = Number(raw.extracted_budget || 0);

let lead_score = 65;
let status = 'FOLLOWED_UP';

if (budget >= 70000000) {
  lead_score = 100;
  status = 'PRIORITY_SALES';
} else if (budget >= 25000000) {
  lead_score = 85;
  status = 'QUALIFIED';
} else {
  lead_score = 65;
  status = 'FOLLOWED_UP';
}

if (raw.clean_phone && raw.clean_phone.length >= 10) {
  lead_score = Math.min(100, lead_score + 5);
}

const is_existing = Boolean(dbCheck && dbCheck.id);

return [{
  json: {
    ...raw,
    existing_customer_id: is_existing ? dbCheck.id : null,
    is_existing,
    lead_score,
    lead_status: status
  }
}];

