}];

const current = $('9. Assign Sales Representative Code').first().json;

return [{
  json: {
    status: "ENQUEUED_FOR_NURTURING",
    customer_email: current.sender_email,
    deal_id: current.deal_id,
    lead_score: current.lead_score,
    campaign_tag: current.campaign_tag,
